{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '서운함이 너무 오래 혼자 있었다면 그렇게 느껴질 수 있을 것 같다'며 억눌린 감정을 언급한 것에 대해, 내담자의 핵심 신념(내 욕구보다 남의 욕구가 먼저, 나를 앞세우는 것은 이기적)이 이 서운함을 느끼지 못하게 막아온 구조를 설명함. 성장 경험에서 '이기적이다'라는 핀잔이 반복된 것이 이 신념의 근원."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 '힘든 걸 인정하면 힘든 척하는 것 같다'고 말한 것은 '내 필요나 힘듦을 앞세우는 것은 이기적이고 부끄러운 일'이라는 태도와 직접 연결됨. 상황 사례에서 어머니가 명절 준비를 당연하게 맡길 때 '왜 아무도 나한테는 힘드냐고 안 물어보지'라는 서운함이 올라왔지만 즉시 죄책감으로 억눌렀음."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '그걸 느낄 틈을 안 만든다'고 말한 것은 '힘들어도 내색하지 않아야 한다'는 규칙의 작동 방식임. 상황 사례에서 몸살이 있는데도 후배 교대를 수락하고 가족에게 아프다는 말을 하지 않은 것이 이 규칙의 구체적 예시."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/3"],
      "relevance": "상담사가 '그 틈을 잠깐이라도 만들면 어떤 게 올라올 것 같으세요'라고 물었을 때 내담자가 '서운한 게 올라올 것 같은데 감당이 안 될 것 같다'고 답한 것은, 평소 자기 상태를 숨기는 전략이 서운함 자체를 느끼지 못하게 차단해온 결과임. 상황 사례에서 배우자가 '당신은 뭘 원하는지 모르겠다'고 물었을 때 답하지 못한 것이 이 전략의 극단적 결과."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": [],
      "relevance": "상담사가 '멈출 수 없을 것 같다'는 내담자의 두려움에 대해 안전한 속도로 느끼면 된다고 말한 것은, 서운함이 한꺼번에 올라오면 폭발로 이어지고 다시 죄책감으로 억누르는 악순환을 차단하려는 개입과 연결됨."
    }
  ]
}

